"""Migrated invoiced-order workflow, validation, and total recomputation rules."""

from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    """A legacy business validation failure."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(code, message)


_CENTS = Decimal("0.01")


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL/numeric-context behavior for missing or blank values."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def _is_deleted(row: dict) -> bool:
    """Legacy blank DEL_FLG means N; only Y is logically deleted."""
    return row.get("DEL_FLG") == "Y"


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the documented invoiced-order cancellation transition."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    result = dict(order)

    if new_status == "I":
        return result, [], []

    if new_status == "X":
        result["STAT_CD"] = "X"
        return result, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live line extensions and the discounted order total."""
    result_order = dict(order)
    result_lines = [dict(line) for line in lines]

    # Invoiced and cancelled headers are frozen. Deleted headers are not live reads.
    if result_order.get("STAT_CD") in {"I", "X"} or _is_deleted(result_order):
        return result_order, result_lines, []

    total = Decimal("0")

    for line in result_lines:
        if _is_deleted(line):
            continue

        extension = _round_cents(
            _numeric(line.get("QTY")) * _numeric(line.get("UNIT_PRC"))
        )
        line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _round_cents(
        total * (Decimal("100") - _numeric(result_order.get("DISC_PCT")))
        / Decimal("100")
    )

    previous_total = _numeric(result_order.get("TOT_AMT"))
    result_order["TOT_AMT"] = float(discounted_total)

    audits = ["ORD_RETOTAL"] if previous_total != discounted_total else []
    return result_order, result_lines, audits
